#include <cctype>
#include <string>

struct Version { int major{ 0 }; int minor{ 0 }; int patch{ 0 }; std::string pre; };

static bool number(const std::string& s, int& out)
{
    if (s.empty() || s.size() > 9) return false;
    for (char c : s) if (!std::isdigit(static_cast<unsigned char>(c))) return false;
    if (s.size() > 1 && s[0] == '0') return false;
    out = std::stoi(s);
    return true;
}

bool parseVersion(const std::string& text, Version& out)
{
    std::string core{ text };
    std::string pre;
    const auto dash{ text.find('-') };
    if (dash != std::string::npos)
    {
        core = text.substr(0, dash);
        pre = text.substr(dash + 1);
        if (pre.empty()) return false;
    }
    const auto d1{ core.find('.') };
    if (d1 == std::string::npos) return false;
    const auto d2{ core.find('.', d1 + 1) };
    if (d2 == std::string::npos || core.find('.', d2 + 1) != std::string::npos) return false;
    Version v;
    if (!number(core.substr(0, d1), v.major) || !number(core.substr(d1 + 1, d2 - d1 - 1), v.minor) || !number(core.substr(d2 + 1), v.patch)) return false;
    v.pre = pre;
    out = v;
    return true;
}

int compareVersions(const Version& a, const Version& b)
{
    if (a.major != b.major) return a.major < b.major ? -1 : 1;
    if (a.minor != b.minor) return a.minor < b.minor ? -1 : 1;
    if (a.patch != b.patch) return a.patch < b.patch ? -1 : 1;
    if (a.pre == b.pre) return 0;
    if (a.pre.empty()) return 1;
    if (b.pre.empty()) return -1;
    return a.pre < b.pre ? -1 : 1;
}

bool compatible(const Version& builtAgainst, const Version& running)
{
    return running.major == builtAgainst.major && compareVersions(running, builtAgainst) >= 0;
}

std::string nextVersion(const Version& current, const std::string& change)
{
    Version v{ current.major, current.minor, current.patch, "" };
    if (change == "break") { ++v.major; v.minor = 0; v.patch = 0; }
    else if (change == "add") { ++v.minor; v.patch = 0; }
    else if (change == "fix") { ++v.patch; }
    return std::to_string(v.major) + "." + std::to_string(v.minor) + "." + std::to_string(v.patch);
}

unitTests:
Version V(const char* s) { Version v; parseVersion(s, v); return v; }
TEST("parse") { Version v; CHECK(parseVersion("2.4.1", v)); CHECK_EQ(v.major, 2); CHECK_EQ(v.minor, 4); CHECK_EQ(v.patch, 1); CHECK_EQ(v.pre, std::string("")); CHECK(parseVersion("3.0.0-beta.2", v)); CHECK_EQ(v.pre, std::string("beta.2")); CHECK(parseVersion("0.0.0", v)); }
TEST("reject") { Version v; CHECK(!parseVersion("2.4", v)); CHECK(!parseVersion("2.4.1.0", v)); CHECK(!parseVersion("2.04.1", v)); CHECK(!parseVersion("a.b.c", v)); CHECK(!parseVersion("1.2.3-", v)); CHECK(!parseVersion("", v)); CHECK(!parseVersion("1..2", v)); }
TEST("compare as numbers") { CHECK_EQ(compareVersions(V("2.10.0"), V("2.9.0")), 1); CHECK_EQ(compareVersions(V("1.0.0"), V("1.0.1")), -1); CHECK_EQ(compareVersions(V("3.1.4"), V("3.1.4")), 0); }
TEST("pre-releases are older") { CHECK_EQ(compareVersions(V("3.0.0-beta.2"), V("3.0.0")), -1); CHECK_EQ(compareVersions(V("3.0.0-alpha"), V("3.0.0-beta")), -1); CHECK_EQ(compareVersions(V("3.0.0-rc"), V("2.9.9")), 1); }
TEST("compatible") { CHECK(compatible(V("2.3.0"), V("2.5.1"))); CHECK(compatible(V("2.3.0"), V("2.3.0"))); CHECK(!compatible(V("2.3.0"), V("2.2.9"))); CHECK(!compatible(V("2.3.0"), V("3.0.0"))); CHECK(!compatible(V("2.3.0"), V("1.9.0"))); }
TEST("next version") { CHECK_EQ(nextVersion(V("1.6.3"), "add"), std::string("1.7.0")); CHECK_EQ(nextVersion(V("1.6.3"), "break"), std::string("2.0.0")); CHECK_EQ(nextVersion(V("1.6.3"), "fix"), std::string("1.6.4")); CHECK_EQ(nextVersion(V("3.0.0-rc.1"), "fix"), std::string("3.0.1")); }

